const ready=page=>page.waitForFunction(()=>[...document.querySelectorAll('[aria-busy="true"]')].every(el=>el.getClientRects().length===0),{},{timeout:12000});
const statValues=scope=>scope.locator('.workspace-stat > strong').evaluateAll(nodes=>nodes.map(node=>{const copy=node.cloneNode(true);copy.querySelectorAll('.visually-hidden').forEach(el=>el.remove());return copy.textContent;}));
const menu=(page,name)=>page.getByRole('navigation',{name:'관리자 메뉴',exact:true}).getByRole('button',{name,exact:true});
async function select(page,label,option){await page.getByRole('combobox',{name:new RegExp(`^${label}:`)}).click();await page.getByRole('option',{name:option,exact:true}).click();await page.getByRole('listbox',{name:label,exact:true}).waitFor({state:'hidden'});}
async function tab(page,name){await page.getByRole('tab',{name,exact:true}).click();await ready(page);}
async function closeDialog(page){await page.getByRole('dialog').getByRole('button',{name:'닫기',exact:true}).click();await page.getByRole('dialog').waitFor({state:'hidden'});}
async function openFixture(page,index=0,edit=false){await page.locator('.fixture-schedule-table tbody tr').nth(index).locator('td').last().click();const modal=page.getByRole('dialog',{name:'경기 일정 정보',exact:true});await modal.waitFor();if(edit)await modal.getByRole('button',{name:'일정 수정',exact:true}).click();return modal;}
async function run(browser,name,callback,options={}){
 if(process.env.QA_FILTER&&!new RegExp(process.env.QA_FILTER).test(name))return;
 const context=await browser.newContext({viewport:{width:1440,height:1000},reducedMotion:'reduce',acceptDownloads:true,...options.context});
 await context.addInitScript(({theme,initial})=>{localStorage.setItem('kickon-admin-theme',theme);window.qaInitial=initial},{theme:options.theme||'light',initial:options.initial||{}});
 await context.route('**/*',route=>{const url=new URL(route.request().url());if(url.origin!==base)return route.abort();if(url.pathname==='/api/admin/system-metrics'&&options.initial?.monitoring){const payload=monitoringFixture(options.initial.monitoring,route.request().postDataJSON().range);payload.restart={allowed:['admin','super_admin'].includes(options.role||'admin'),configured:Boolean(options.initial.restart),projectRef:'a'.repeat(20),cooldownUntil:null};return route.fulfill({json:payload});}if(url.pathname==='/api/admin/project-restart'){if(!options.initial?.restart)return route.abort();const body=route.request().postDataJSON();return (async()=>{await page.evaluate(body=>window.qa.writes.push({name:'project-restart',body}),body);await new Promise(resolve=>setTimeout(resolve,600));return options.initial.restart==='error'?route.fulfill({status:503,json:{error:'QA 재시작 요청을 처리하지 못했어요'}}):route.fulfill({status:202,json:{status:options.initial.restart,cooldownUntil:new Date(Date.now()+300000).toISOString(),message:options.initial.restart==='accepted'?'DB 서버 재시작 요청을 보냈어요 복구 상태는 모니터링에서 확인해 주세요':'재시작 요청의 처리 결과를 확인할 수 없어요 모니터링을 확인하고 중복 요청을 피해주세요'}});})();}if(url.pathname==='/preview-qa')return route.fulfill({contentType:'text/html',body:html(options.role||'admin',url.searchParams.get('qaScreen')==='login'?'login':'dashboard')});if(url.pathname==='/src/auth/client.ts')return route.fulfill({contentType:'application/javascript',body:options.initial?.environment==='production'?authFixture.replace("authEnvironment='development'","authEnvironment='production'"):authFixture});if(url.pathname==='/src/management/data.ts')return route.fulfill({contentType:'application/javascript',body:managementFixture});return route.continue()});
 const page=await context.newPage();page.setDefaultTimeout(12000);const errors=[];page.on('pageerror',error=>errors.push(error.message));const start=Date.now();
 try{await page.goto(`${base}/preview-qa?page=${options.page||'dashboard'}${options.tab?`&tab=${options.tab}`:''}${options.push?`&push=${options.push}`:''}${options.sync?`&sync=${options.sync}`:''}`);await page.locator('.dashboard-header').waitFor();await callback(page,context);assert.deepEqual(errors,[],'No unhandled browser errors');results.push({name,passed:true,durationMs:Date.now()-start});console.log(`PASS ${name}`)}catch(error){await page.screenshot({path:path.join(artifacts,`failure-${results.length}.png`),fullPage:true}).catch(()=>{});results.push({name,passed:false,error:error.message,stack:error.stack,browserErrors:errors});console.error(`FAIL ${name}: ${error.message}`)}finally{await context.close()}
 fs.writeFileSync(path.join(artifacts,'results.json'),JSON.stringify(results,null,2));
}
async function auditDropdowns(page,scope){
 scope=scope??(await page.getByRole('dialog').count()?page.getByRole('dialog'):page);
 const combos=scope.getByRole('combobox');const count=await combos.count();
 for(let index=0;index<count;index++){
  const combo=combos.nth(index);await combo.scrollIntoViewIfNeeded();const alignment=await combo.evaluate(el=>{const box=el.getBoundingClientRect(),arrow=el.querySelector('.seed-select-trigger__suffixIcon').getBoundingClientRect(),value=el.querySelector('.seed-select-trigger__value').getBoundingClientRect(),style=getComputedStyle(el);return {name:el.getAttribute('aria-label'),inset:box.right-arrow.right,padding:parseFloat(style.paddingRight),separated:value.right<=arrow.left-6,height:box.height,valueCenter:(value.top+value.bottom)/2,arrowCenter:(arrow.top+arrow.bottom)/2}});assert.ok(Math.abs(alignment.inset-alignment.padding)<1,JSON.stringify(alignment));assert.equal(alignment.separated,true,JSON.stringify(alignment));assert.ok(Math.abs(alignment.valueCenter-alignment.arrowCenter)<2,JSON.stringify(alignment));assert.ok(alignment.height>=40,JSON.stringify(alignment));
  const dialogsBefore=await page.getByRole('dialog').count();await combo.click();const list=page.getByRole('listbox');await list.waitFor();assert.equal(await list.evaluate(el=>{const r=el.getBoundingClientRect();return r.width>=159&&r.left>=0&&r.right<=innerWidth&&r.top>=0&&r.bottom<=innerHeight}),true);const option=page.getByRole('option').first();await option.scrollIntoViewIfNeeded();assert.equal(await option.evaluate(el=>{const r=el.getBoundingClientRect();return el.contains(document.elementFromPoint(r.left+r.width/2,r.top+r.height/2))}),true);await page.keyboard.press('Escape');await list.waitFor({state:'hidden'});assert.equal(await page.getByRole('dialog').count(),dialogsBefore,'Escape closes the dropdown before its parent dialog');
 }
 return count;
}
